The reference walks time from 0 to 16. At each step it first adds a token if one arrives (only when the bucket isn't full), then serves every request at that moment. `post` compares this independent count with `result`.

```python
def pre(times):
    if len(times) > 6:
        return False
    for t in times:
        if t < 0 or t > 16:
            return False
    for i in range(len(times) - 1):
        if times[i] > times[i + 1]:
            return False
    return True


def expected_admits(times):
    tokens = 3
    admitted = 0
    for s in range(17):
        # Token arrivals at 4, 8, 12, 16 come before requests at the same time.
        # A token that arrives when the bucket is full is discarded.
        if s > 0 and s % 4 == 0 and tokens < 3:
            tokens += 1
        # Serve all requests that arrive at time s, in order.
        for t in times:
            if t == s:
                if tokens > 0:
                    tokens -= 1
                    admitted += 1
    return admitted


def post(times, result):
    return result == expected_admits(times)
